mapper.select:
SELECT * FROM USERS
WHERE OAUTH_PROVIDER = #{provider}
  AND OAUTH_PROVIDER_ID = #{providerId}
  AND DELETED_AT IS NULL

SELECT * FROM USERS
WHERE NAME = #{name}
  AND PHONE = #{phone}
  AND DELETED_AT IS NULL
ORDER BY CREATED_AT ASC
LIMIT 1

SELECT * FROM USERS
WHERE EMAIL = #{email}
  AND PHONE = #{phone}
  AND DELETED_AT IS NULL
LIMIT 1

SELECT EXISTS (
    SELECT 1 FROM USERS WHERE EMAIL = #{email} AND DELETED_AT IS NULL
)

mapper.update:
UPDATE USERS
SET LAST_LOGIN_AT = #{loginAt}
WHERE USER_ID = #{userId}

UPDATE USERS
SET PASSWORD_HASH = #{passwordHash}
WHERE USER_ID = #{userId}

UPDATE USERS
SET OAUTH_PROVIDER = #{provider},
    OAUTH_PROVIDER_ID = #{providerId}
WHERE USER_ID = #{userId}

UPDATE USERS
SET STATUS = 'WITHDRAWN',
    DELETED_AT = #{deletedAt}
WHERE USER_ID = #{userId}
